# frozen_string_literal: true

require "mkmf"
require "rb_sys/mkmf"

# The Rust extension path-depends on the vendored engine. In a checkout it is
# generated by `rake compile` / `scripts/vendor-engine.sh`; a built gem ships
# its own copy. Fail with a clear message rather than a cargo error.
engine = File.expand_path("../../vendor/engine/crates/zipp-vm", __dir__)
unless File.directory?(engine)
  abort <<~MSG
    zipp-rb: the vendored Zipp engine is missing (#{engine}).
    From a source checkout, run: scripts/vendor-engine.sh
    (or `rake compile`, which runs it). A built .gem includes it already.
  MSG
end

# Build the Rust cdylib and install it as lib/zipp_rb/zipp_rb.<ext>.
create_rust_makefile("zipp_rb/zipp_rb")
